      if (this.index.nodes.has(notePath)) this.selectNode(notePath);
      new Notice(`\u8BBA\u6587 stub \u5DF2\u521B\u5EFA:${folderName}(tags/pdf \u5F85\u8865,\u8865\u5B8C\u8DD1 lint)`);
