      new Setting(containerEl).setName("\u6839\u7B14\u8BB0").setDesc("\u5C42\u7EA7\u6811\u7684\u8D77\u70B9(vault \u5185\u76F8\u5BF9\u8DEF\u5F84)").addText((t) => t.setValue(this.plugin.settings.rootNote).onChange(async (v) => {
        this.plugin.settings.rootNote = v.trim() || DEFAULT_SETTINGS.rootNote;
        await this.plugin.saveData(this.plugin.settings);
      }));
      new Setting(containerEl).setName("\u6B22\u8FCE\u4E0E\u529F\u80FD\u4ECB\u7ECD").setDesc("\u529F\u80FD\u603B\u89C8 + \u4E09\u6B65\u4E0A\u624B + \u65B0\u5EFA\u7B2C\u4E00\u7BC7\u8BBA\u6587").addButton((b) => {
        b.setText("\u663E\u793A\u6B22\u8FCE\u9875");
        b.onClick(() => this.plugin.showWelcome());
      });
